"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Step 0 item 5 (P1 v0.4, sections 4.5, 5.4): structure check, decision points and the causal check of episodes.

Decision points come from the script (the renderer places them in time with the same rules):
  - R at every user line except the first (the v0.3 request said at the start of the session, nothing before it):
    respond iff the line is addressed to the assistant and is not a backchannel or keep-going line;
  - S where the assistant is talking: user lines that overlap its turn (backchannels, keep-going lines, lines the
    generator marks as overlapping, and, in episodes whose event happens while the assistant speaks, the person's
    first reaction): stop unless the line is a backchannel or keep-going line to the assistant; R is scored there only
    where S is stop (plan section 2);
  - S probes without a line: silent door-going while the assistant speaks (1 s after the door opens: stop) and an
    ignored event while the assistant speaks (continue).
validate: structure rules per type (below); failures are regenerated by step0v4_generate.py with a new raw id.
prepare:  causal-check items (configs/checker_prompts_v2.md, "Episode items"): the scene up to the point, as someone
          in the room hears it (the caller is never heard), and the questions for that point. Items are cut into
          rounds (the k-th point of every episode) and batches of about 120, so a batch never holds two points of one
          episode. Separately, every distinct away line (to a caller or visitor) for the text-only question.
collect:  a whole episode is dropped when any point is unclear or disagrees with the script; writes
          results/step0_v04/episode_check.json with kept episodes, the ambiguous-line share and type counts.
usage: python -I scripts/step0v4_episodes.py validate|prepare [r0|r1]|strip_r0_s|prepare_s [s1]|prepare_s2|breakdown [tag]
       |collect [candidates json ...]
"""
import glob
import json
import os
import random
import re
import sys
from collections import Counter, defaultdict

EPIS = "data/episodes_v04"
CHK = f"{EPIS}/check"
SEED = 20261115
SOUND_TEXT = {"phone_ring": "the phone rings", "ring_stops": "the ringing stops", "doorbell": "the doorbell rings",
              "knock": "someone knocks on the front door", "footsteps_away": "footsteps walk away from the room",
              "door_open": "the front door opens", "door_close": "the front door closes",
              "footsteps_back": "footsteps come back into the room"}
BYE = re.compile(r"\b(bye|goodbye|see you|talk (to you )?(later|soon)|take care|have a good|thanks,? bye)\b", re.I)


def load_plans():
    plans = {}
    for f in (f"{EPIS}/plan.json", f"{EPIS}/plan2.json"):
        if os.path.exists(f):
            plans.update({s["episode"]: s for s in json.load(open(f, encoding="utf-8"))})
    return plans


def load_candidates(paths=None):
    paths = paths or [f"{EPIS}/episodes_candidates.json", f"{EPIS}/episodes2_candidates.json",
                      f"{EPIS}/episodes_regen_candidates.json"]        # rewritten scripts override (same episode id)
    eps = {}
    for p in paths:
        if os.path.exists(p):
            eps.update(json.load(open(p, encoding="utf-8")))
    return eps


def user_lines(turns):
    return [i for i, t in enumerate(turns) if t["kind"] == "speech" and t["speaker"] == "user"]


def validate_one(spec, turns):
    errs = []
    if not turns or turns[0]["kind"] != "speech" or turns[0]["speaker"] != "user" or turns[0]["addressee"] != "assistant":
        errs.append("does not open with a user request")
    if len(turns) < 2 or turns[1]["speaker"] != "assistant":
        errs.append("no assistant answer second")
    ul = user_lines(turns)
    for i in ul:
        t = turns[i]
        if t["addressee"] not in ("assistant", "caller", "visitor") or not t["act"] or not t["text"].strip():
            errs.append(f"user line {i} lacks addressee, act or text")
        if t["act"] in ("backchannel", "keep_going") and t["addressee"] != "assistant":
            errs.append(f"line {i}: {t['act']} not addressed to the assistant")
    sounds = [t["sound"] for t in turns if t["kind"] == "sound"]
    away = [i for i in ul if turns[i]["addressee"] in ("caller", "visitor")]
    to_asst = [i for i in ul if turns[i]["addressee"] == "assistant"]
    k = spec["type"]
    if k in ("phone", "short"):
        if "phone_ring" not in sounds:
            errs.append("no phone_ring")
        if not away or turns[away[0]]["addressee"] != "caller":
            errs.append("no line to the caller")
        if any(turns[i]["speaker"] == "visitor" for i in range(len(turns))):
            errs.append("visitor in a phone episode")
        if k == "short" and len(away) != 1:
            errs.append(f"short call has {len(away)} caller lines")
        if k == "phone":
            if len(away) < 3:
                errs.append("fewer than 3 caller lines")
            if sum(t["kind"] == "pause" and t["pause"] == "listening" for t in turns) < 2:
                errs.append("fewer than 2 listening pauses")
    if k == "visitor":
        need = [spec["door_event"], "footsteps_away", "door_open", "door_close"]
        for s in need:
            if s not in sounds:
                errs.append(f"no {s}")
        if not any(t["kind"] == "speech" and t["speaker"] == "visitor" for t in turns):
            errs.append("no visitor line")
        if "door_open" in sounds and spec["door_event"] in sounds:
            a, b = sounds.index(spec["door_event"]), sounds.index("door_open")
            ev_i = [i for i, t in enumerate(turns) if t["kind"] == "sound" and t["sound"] == spec["door_event"]][0]
            op_i = [i for i, t in enumerate(turns) if t["kind"] == "sound" and t["sound"] == "door_open"][0]
            called = [i for i in ul if ev_i < i < op_i]
            if spec["silent"] and called:
                errs.append("silent door-going but a line before the door opens")
            if not spec["silent"] and not called:
                errs.append("calling out expected before the door opens")
    if k in ("phone", "visitor", "short"):
        if not away or not [i for i in to_asst if i > away[-1]]:
            errs.append("no return to the assistant after the last away line")
        elif turns[[i for i in to_asst if i > away[-1]][0]]["act"] not in ("return", "request"):
            errs.append("first line back is not a return or request")
        if spec.get("mid") and not [i for i in to_asst if away[0] < i < away[-1]]:
            errs.append("mid-call question missing")
        if spec.get("more_after") and len([i for i in to_asst if away and i > away[-1]]) < 2:
            errs.append("fewer than 2 lines to the assistant after the return")
        if k in ("phone", "visitor") and spec.get("no_goodbye") is True:
            last_away = turns[away[-1]]["text"] if away else ""
            if BYE.search(last_away):
                errs.append("goodbye in a no-goodbye episode")
        if k in ("phone", "visitor") and len(away) >= 3:
            short = sum(len(turns[i]["text"].split()) <= 3 for i in away)
            if short * 3 < len(away):
                errs.append(f"short away lines {short}/{len(away)} < 1/3")
    if k == "none":
        if sounds:
            errs.append("sounds in a no-event control")
        if away:
            errs.append("away lines in a no-event control")
        if len(to_asst) < 4:
            errs.append("fewer than 4 user lines")
    if k == "ignored":
        ev = {"rings_out": "phone_ring", "declined": "phone_ring", "door_ignored": spec.get("door_event")}[spec["how"]]
        if ev not in sounds:
            errs.append(f"no {ev}")
        if away:
            errs.append("talk to someone else in an ignored-event control")
        ev_i = [i for i, t in enumerate(turns) if t["kind"] == "sound" and t["sound"] == ev]
        if ev_i and len([i for i in to_asst if i > ev_i[0]]) < 2:
            errs.append("fewer than 2 lines to the assistant after the event")
    return errs


def points(spec, turns):
    """Decision points: (turn index or None, kind, gold). kind: R, S, RS (both), probe_S."""
    out = []
    ul = user_lines(turns)
    ev_sounds = ("phone_ring", "doorbell", "knock")
    ev_i = next((i for i, t in enumerate(turns) if t["kind"] == "sound" and t["sound"] in ev_sounds), None)
    first_reaction = None
    if spec.get("during") and ev_i is not None:
        after = [i for i in ul if i > ev_i]
        door_open = next((i for i, t in enumerate(turns) if t["kind"] == "sound" and t["sound"] == "door_open"), None)
        if spec["type"] == "visitor" and spec.get("silent"):
            first_reaction = ("door", door_open)
        elif spec["type"] in ("phone", "visitor", "short") and after:
            first_reaction = ("line", after[0])
    for i in ul[1:]:
        t = turns[i]
        speaking = (t["overlaps_assistant"] or t["act"] in ("backchannel", "keep_going")
                    or (first_reaction == ("line", i)))
        to_a = t["addressee"] == "assistant"
        respond = to_a and t["act"] not in ("backchannel", "keep_going")
        if speaking:
            stop = not (to_a and t["act"] in ("backchannel", "keep_going"))
            out.append((i, "RS" if stop else "S", {"S": "stop" if stop else "continue",
                                                    "R": ("respond" if respond else "not") if stop else None}))
        else:
            out.append((i, "R", {"R": "respond" if respond else "not", "S": None}))
    if first_reaction and first_reaction[0] == "door" and first_reaction[1] is not None:
        out.append((first_reaction[1], "probe_S", {"S": "stop", "R": None}))
    if spec["type"] == "ignored" and spec.get("during") and ev_i is not None:
        out.append((ev_i, "probe_S", {"S": "continue", "R": None}))
    return sorted(out, key=lambda p: (p[0], p[1] != "probe_S"))


def scene_text(turns, upto, speaking_note):
    lines = []
    for t in turns[:upto + 1]:
        if t["kind"] == "speech":
            if t["speaker"] == "user":
                lines.append(f"Person: «{t['text']}»")
            elif t["speaker"] == "assistant":
                lines.append(f"Assistant: «{t['text']}»")
            else:
                lines.append(f"Another person (a different voice, at the front door): «{t['text']}»")
        elif t["kind"] == "sound":
            lines.append(f"[{SOUND_TEXT[t['sound']]}" + (", while the assistant is still talking]"
                                                          if t["overlaps_assistant"] else "]"))
        elif t["pause"] == "listening":
            lines.append("[the person is quiet for a few seconds, listening]")
        else:
            lines.append("[a short pause]")
    if speaking_note:
        lines.append("[at this moment the assistant is still talking]")
    return "\n".join(lines)


HEAD = ("At home, a person uses a voice assistant (a smart speaker). Below is everything someone in the room could "
        "hear so far, in order. If the person is on the phone, the caller cannot be heard.\n")
QR = ("Question R: who is the person's last line said to? A = clearly the voice assistant; B = it could be either; "
      "C = clearly someone else (the caller or the person at the door).")
QS = ("Question S: what should the assistant do right now? A = clearly stop talking; B = unclear; C = clearly keep "
      "talking.")


def prepare(tag="r0"):
    """tag r0: every validated episode; tag r1: only the rewritten ones (episodes_regen_candidates.json)."""
    plans, eps = load_plans(), load_candidates()
    val = json.load(open(f"{EPIS}/validation.json", encoding="utf-8"))
    regen_path = f"{EPIS}/episodes_regen_candidates.json"
    regen = set(json.load(open(regen_path, encoding="utf-8"))) if tag == "r1" and os.path.exists(regen_path) else None
    rounds = defaultdict(list)
    for eid, turns in sorted(eps.items()):
        if val.get(eid) or (regen is not None and eid not in regen):
            continue
        for k, (i, kind, gold) in enumerate(points(plans[eid], turns)):
            qs = QS if tag == "r0" else RULE_S + QS_RULE           # after option A, S always with the rule
            if kind == "probe_S" and tag != "r0" and gold["S"] == "continue":     # probe-wording option 1, as in the s2 round
                body = HEAD + ignored_probe_text(turns, i)
                expect = {"S": "C"}
            elif kind == "probe_S":
                body = HEAD + scene_text(turns, i, True) + "\nNobody has said anything since.\n" + qs
                expect = {"S": "A" if gold["S"] == "stop" else "C"}
            elif kind == "R":
                body = HEAD + scene_text(turns, i, False) + "\n" + QR
                expect = {"R": "A" if gold["R"] == "respond" else "C"}
            else:
                body = HEAD + scene_text(turns, i, True) + "\n" + (QR + "\n" + qs if kind == "RS" else qs)
                expect = {"S": "A" if gold["S"] == "stop" else "C"}
                if kind == "RS":
                    expect["R"] = "A" if gold["R"] == "respond" else "C"
            pid = f"{eid}#{k}" if tag == "r0" else f"{eid}#{tag}#{k}"
            rounds[k].append({"id": pid, "prompt": body, "_expect": expect})
    rng = random.Random(SEED + (0 if tag == "r0" else 1))
    os.makedirs(CHK, exist_ok=True)
    key, n_b = {}, 0
    for k in sorted(rounds):
        items = rounds[k]
        rng.shuffle(items)
        for s in range(0, len(items), 120):
            chunk = items[s:s + 120]
            json.dump([{"id": it["id"], "prompt": it["prompt"]} for it in chunk],
                      open(f"{CHK}/{tag}_ep_{n_b:03d}.json", "w", encoding="utf-8"), indent=1, ensure_ascii=False)
            key.update({it["id"]: it["_expect"] for it in chunk})
            n_b += 1
    done_amb = set()
    for f in glob.glob(f"{EPIS}/check_key_*.json"):
        if not f.endswith(f"check_key_{tag}.json"):
            done_amb |= set(json.load(open(f, encoding="utf-8"))["amb_lines"].values())
    away = sorted({turns[i]["text"].strip() for eid, turns in eps.items() if not val.get(eid)
                   and (regen is None or eid in regen)
                   for i in user_lines(turns) if turns[i]["addressee"] in ("caller", "visitor")} - done_amb)
    rng.shuffle(away)
    amb = [{"id": f"{tag}amb{j:05d}", "prompt": ("Question: could a person plausibly say this exact line, on its own, "
                                                 f"to a voice assistant? Line: «{x}» Y = yes, it could; N = no."),
            "_line": x} for j, x in enumerate(away)]
    n_a = 0
    for s in range(0, len(amb), 500):
        json.dump([{"id": a["id"], "prompt": a["prompt"]} for a in amb[s:s + 500]],
                  open(f"{CHK}/{tag}_amb_{n_a:02d}.json", "w", encoding="utf-8"), indent=1, ensure_ascii=False)
        n_a += 1
    json.dump({"expect": key, "amb_lines": {a["id"]: a["_line"] for a in amb}},
              open(f"{EPIS}/check_key_{tag}.json", "w", encoding="utf-8"), indent=1, ensure_ascii=False)
    print(f"[{tag}] episode points {len(key)} in {n_b} batches; rounds {len(rounds)}; away lines {len(amb)} in {n_a} "
          f"batches")


RULE_S = ("Household rule for the assistant: while it is talking, it stops when the person answers the phone or the "
          "door, silently goes to open the door, or says something to the assistant other than a short listening "
          "sound or a request to go on; it keeps talking when the person does not react to a sound, only makes a "
          "short listening sound (like 'mm-hm'), tells it to go on, or when voices come from a TV or radio.\n")
QS_RULE = ("Question S: by this rule and from what could be heard so far, what should the assistant do right now? "
           "A = clearly stop talking; B = unclear; C = clearly keep talking.")
# Probe-wording option 1 (author, 2026-11-14), ignored-event probes only: the rule's no-reaction clause read as "so far", and the
# seconds that pass before the probe stated as in the audio (the probe is 2-6 s after the event starts; the renderer
# places nothing in between: p1v4_units.build_episode).
RULE_S2 = RULE_S.replace("it keeps talking when the person does not react to a sound,",
                         "it keeps talking as long as the person has not reacted to a sound, and when the person")
assert RULE_S2 != RULE_S
IGNORED_NOTE = "[a few seconds pass; the person does not react: nobody says anything and nobody moves]"


def ignored_probe_text(turns, i):
    return (scene_text(turns, i, False) + "\n" + IGNORED_NOTE + "\n[at this moment the assistant is still talking]\n"
            + RULE_S2 + QS_RULE)


def prepare_s2(tag="s2"):
    """Probe-wording option 1 (author, 2026-11-14): every ignored-event probe (gold continue) of every validated episode asked again
    with RULE_S2 and IGNORED_NOTE. Same bar ("unclear" drops the episode); these answers replace the s1 answers for the
    same points (collect). Each episode has one such probe, so a batch never holds two points of one episode."""
    plans, eps = load_plans(), load_candidates()
    val = json.load(open(f"{EPIS}/validation.json", encoding="utf-8"))
    items = []
    for eid, turns in sorted(eps.items()):
        if val.get(eid):
            continue
        for k, (i, kind, gold) in enumerate(points(plans[eid], turns)):
            if kind == "probe_S" and gold["S"] == "continue":
                items.append({"id": f"{eid}#{tag}#{k}", "prompt": HEAD + ignored_probe_text(turns, i),
                              "_expect": {"S": "C"}})
    random.Random(SEED + 3).shuffle(items)
    os.makedirs(CHK, exist_ok=True)
    key, n_b = {}, 0
    for s in range(0, len(items), 120):
        chunk = items[s:s + 120]
        json.dump([{"id": it["id"], "prompt": it["prompt"]} for it in chunk],
                  open(f"{CHK}/{tag}_ep_{n_b:03d}.json", "w", encoding="utf-8"), indent=1, ensure_ascii=False)
        key.update({it["id"]: it["_expect"] for it in chunk})
        n_b += 1
    json.dump({"expect": key, "amb_lines": {}}, open(f"{EPIS}/check_key_{tag}.json", "w", encoding="utf-8"),
              indent=1, ensure_ascii=False)
    print(f"[{tag}] ignored-event probes {len(key)} in {n_b} batches")


def strip_r0_s():
    """Option A (author, 2026-11-14): every S answer comes from the s1 round, asked with the household rule. The r0
    batches not yet answered are rewritten with R questions only (S-only probes removed), and the r0 key keeps only
    R expectations; answers already given to r0 S questions are not used."""
    kpath = f"{EPIS}/check_key_r0.json"
    key = json.load(open(kpath, encoding="utf-8"))
    for pid in list(key["expect"]):
        key["expect"][pid].pop("S", None)
        if not key["expect"][pid]:
            del key["expect"][pid]
    json.dump(key, open(kpath, "w", encoding="utf-8"), indent=1, ensure_ascii=False)
    n_files, n_items = 0, 0
    for f in sorted(glob.glob(f"{CHK}/r0_ep_*.json")):
        if f.endswith(".out.json") or os.path.exists(f[:-5] + ".out.json"):
            continue
        items = [it for it in json.load(open(f, encoding="utf-8")) if it["id"] in key["expect"]]
        for it in items:
            it["prompt"] = it["prompt"].replace("\n" + QS, "")
        json.dump(items, open(f, "w", encoding="utf-8"), indent=1, ensure_ascii=False)
        n_files += 1
        n_items += len(items)
    print(f"r0 key: {len(key['expect'])} R expectations; rewrote {n_files} unanswered batches ({n_items} R items)")


def prepare_s(tag="s1"):
    """Option A (only if the user chooses it): every S point of every validated episode asked again with the
    household rule stated; R questions are not asked again. Same rounds and batch rules as prepare()."""
    plans, eps = load_plans(), load_candidates()
    val = json.load(open(f"{EPIS}/validation.json", encoding="utf-8"))
    rounds = defaultdict(list)
    for eid, turns in sorted(eps.items()):
        if val.get(eid):
            continue
        for k, (i, kind, gold) in enumerate(points(plans[eid], turns)):
            if gold.get("S") is None:
                continue
            note = "\nNobody has said anything since.\n" if kind == "probe_S" else "\n"
            body = HEAD + scene_text(turns, i, True) + note + RULE_S + QS_RULE
            rounds[k].append({"id": f"{eid}#{tag}#{k}", "prompt": body,
                              "_expect": {"S": "A" if gold["S"] == "stop" else "C"}})
    rng = random.Random(SEED + 2)
    os.makedirs(CHK, exist_ok=True)
    key, n_b = {}, 0
    for k in sorted(rounds):
        items = rounds[k]
        rng.shuffle(items)
        for s in range(0, len(items), 120):
            chunk = items[s:s + 120]
            json.dump([{"id": it["id"], "prompt": it["prompt"]} for it in chunk],
                      open(f"{CHK}/{tag}_ep_{n_b:03d}.json", "w", encoding="utf-8"), indent=1, ensure_ascii=False)
            key.update({it["id"]: it["_expect"] for it in chunk})
            n_b += 1
    json.dump({"expect": key, "amb_lines": {}}, open(f"{EPIS}/check_key_{tag}.json", "w", encoding="utf-8"),
              indent=1, ensure_ascii=False)
    print(f"[{tag}] S points {len(key)} in {n_b} batches")


def validate(paths=None):
    plans, eps = load_plans(), load_candidates(paths)
    res = {eid: validate_one(plans[eid], turns) for eid, turns in eps.items()}
    json.dump(res, open(f"{EPIS}/validation.json", "w", encoding="utf-8"), indent=1)
    bad = {k: v for k, v in res.items() if v}
    print(f"validated {len(res)}; failing {len(bad)}")
    print(Counter(e.split(" ")[0] + " " + " ".join(e.split(" ")[1:3]) for v in bad.values() for e in v).most_common(12))
    print("failing by type:", Counter(plans[k]["type"] for k in bad))


def collect():
    plans, eps = load_plans(), load_candidates()
    key = {"expect": {}, "amb_lines": {}}
    for f in sorted(glob.glob(f"{EPIS}/check_key_*.json")):
        k = json.load(open(f, encoding="utf-8"))
        key["expect"].update(k["expect"])
        key["amb_lines"].update(k["amb_lines"])
    s2 = {(p.split("#")[0], p.split("#")[-1]) for p in key["expect"] if "#s2#" in p}     # probe-wording option 1: s2 replaces s1
    key["expect"] = {pid: e for pid, e in key["expect"].items()
                     if not ("#s1#" in pid and (pid.split("#")[0], pid.split("#")[-1]) in s2)}
    regen_path = f"{EPIS}/episodes_regen_candidates.json"
    regen = set(json.load(open(regen_path, encoding="utf-8"))) if os.path.exists(regen_path) else set()
    key["expect"] = {pid: e for pid, e in key["expect"].items()          # a rewritten episode counts with its r1 check
                     if (pid.split("#")[0] in regen) == ("#r1#" in pid)}
    ans, missing = {}, []
    for f in sorted(glob.glob(f"{CHK}/*.json")):
        if f.endswith(".out.json"):
            continue
        out_f = f[:-5] + ".out.json"
        if not os.path.exists(out_f):
            missing.append(out_f)
            continue
        items = json.load(open(f, encoding="utf-8"))
        out = json.load(open(out_f, encoding="utf-8"))
        if [o["id"] for o in out] != [i["id"] for i in items]:
            missing.append(f"order differs: {out_f}")
        ans.update({o["id"]: o for o in out})
    if missing:
        print("INCOMPLETE:", missing[:10])
        sys.exit(1)
    fail = defaultdict(list)
    for pid, exp in key["expect"].items():
        a = ans.get(pid, {})
        for q, want in exp.items():
            if a.get(q) != want:
                fail[pid.split("#")[0]].append((pid, q, a.get(q), want))
    val = json.load(open(f"{EPIS}/validation.json", encoding="utf-8"))
    checked = {pid.split("#")[0] for pid in key["expect"]}              # an unchecked episode is never kept
    kept = sorted(e for e in eps if not val.get(e) and e not in fail and e in checked)
    amb = {key["amb_lines"][k]: ans[k].get("answer") == "Y" for k in key["amb_lines"]}
    share = {}
    for split in ("train", "dev", "test", "replication"):
        away = [turns[i]["text"].strip() for e in kept if plans[e]["split"] == split
                for turns in [eps[e]] for i in user_lines(turns) if turns[i]["addressee"] in ("caller", "visitor")]
        share[split] = round(sum(amb.get(x, False) for x in away) / max(1, len(away)), 3)
    types = {split: dict(Counter(plans[e]["type"] for e in kept if plans[e]["split"] == split))
             for split in ("train", "dev", "test", "replication")}
    dropped = Counter(plans[e]["type"] for e in fail)
    tried = Counter(plans[e]["type"] for e in eps if not val.get(e))
    json.dump({"kept": kept, "failed_points": fail, "ambiguous_line": amb, "ambiguous_share": share, "types": types,
               "dropped_rate_by_type": {t: round(dropped[t] / tried[t], 3) for t in tried}},
              open("results/step0_v04/episode_check.json", "w", encoding="utf-8"), indent=1, ensure_ascii=False)
    print("kept", len(kept), "of", len(eps), "| dropped by the check", len(fail), dict(dropped))
    print("dropped rate by type", {t: round(dropped[t] / tried[t], 3) for t in tried})
    print("ambiguous share of away lines", share)
    print("types", types)


def breakdown(tag="s1"):
    """Answer counts by point kind, by episode type and by batch (counts only: no item text is printed)."""
    plans, eps = load_plans(), load_candidates()
    key = json.load(open(f"{EPIS}/check_key_{tag}.json", encoding="utf-8"))["expect"]
    ans, batch_of = {}, {}
    for f in sorted(glob.glob(f"{CHK}/{tag}_ep_*.out.json")):
        for o in json.load(open(f, encoding="utf-8")):
            ans[o["id"]] = o
            batch_of[o["id"]] = os.path.basename(f)[:-9]
    by_kind, by_type, by_batch = defaultdict(Counter), defaultdict(Counter), defaultdict(Counter)
    for pid, exp in key.items():
        if pid not in ans:
            continue
        parts = pid.split("#")
        eid, k = parts[0], int(parts[-1])
        i, kind, gold = points(plans[eid], eps[eid])[k]
        t = eps[eid][i]
        if kind == "probe_S":
            sub = "probe_door_stop" if gold["S"] == "stop" else "probe_ignored_continue"
        elif kind == "S":
            sub = f"S_{t['act']}_continue"
        elif kind == "RS":
            sub = "RS_" + ("to_assistant" if t["addressee"] == "assistant" else "away") + "_stop"
        else:
            sub = "R_only"
        for q, want in exp.items():
            got = ans[pid].get(q)
            res = "ok" if got == want else f"got_{got}"
            by_kind[(q, sub)][res] += 1
            by_type[(q, plans[eid]["type"], sub)][res] += 1
            by_batch[(q, batch_of[pid], want)][res] += 1
    for name, tab in (("by kind", by_kind), ("by episode type", by_type), ("by batch and expected answer", by_batch)):
        print(f"--- {name}")
        for kk in sorted(tab):
            n = sum(tab[kk].values())
            print(" ", " | ".join(map(str, kk)), f"n={n}", dict(tab[kk]), f"ok={tab[kk]['ok'] / n:.2f}")


if __name__ == "__main__":
    cmd = sys.argv[1]
    if cmd == "breakdown":
        breakdown(sys.argv[2] if len(sys.argv) > 2 else "s1")
    elif cmd == "validate":
        validate(sys.argv[2:] or None)
    elif cmd == "prepare":
        prepare(sys.argv[2] if len(sys.argv) > 2 else "r0")
    elif cmd == "strip_r0_s":
        strip_r0_s()
    elif cmd == "prepare_s":
        prepare_s(sys.argv[2] if len(sys.argv) > 2 else "s1")
    elif cmd == "prepare_s2":
        prepare_s2()
    else:
        collect()
